<script setup lang="ts">
import {ref} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {confirm} from '@ai-shop/ui/prompt';import type {ManagementGrant} from '@/api/management-types';import type {MerchantStaff} from '@shared/types';
const {t}=useI18n();const m=ref('');const rows=ref<ManagementGrant[]>([]),resources=ref<ManagementGrant[]>([]),staff=ref<MerchantStaff[]>([]);const actor=ref<MerchantStaff|null>(null),resource=ref<ManagementGrant|null>(null);const next=ref<string|null>(null);const picking=ref<'staff'|'resource'|null>(null);const busy=ref(false),failed=ref(false);
async function load(more=false){try{const page=await api.mManagementResources(m.value,{view:'GRANTS',cursor:more?next.value||undefined:undefined});rows.value=more?[...rows.value,...page.items]:page.items;next.value=page.nextCursor;failed.value=false}catch{failed.value=true}}
async function chooseStaff(){try{staff.value=(await api.mStaffList()).filter(s=>s.status==='ACTIVE');picking.value='staff'}catch{failed.value=true}}
async function chooseResource(){try{const all:ManagementGrant[]=[];let cursor:string|undefined;do{const p=await api.mManagementResources(m.value,{view:'EFFECTIVE',cursor});all.push(...p.items);cursor=p.nextCursor||undefined}while(cursor&&all.length<500);resources.value=all.filter(g=>g.delegatable===true||g.delegatable===1);picking.value='resource'}catch{failed.value=true}}
async function grant(){if(busy.value||!actor.value||!resource.value)return;busy.value=true;try{await api.mManagementGrant(m.value,{actorNo:'MCH:'+actor.value.mchAccountNo,resourceType:resource.value.resourceType,resourceNo:resource.value.resourceNo,permissionCode:resource.value.permissionCode});actor.value=null;resource.value=null;await load()}catch{failed.value=true}finally{busy.value=false}}
async function revoke(row:ManagementGrant){if(busy.value||!await confirm({title:t('management.revoke'),danger:true}))return;busy.value=true;try{await api.mRevokeManagementGrant(m.value,row.grantNo,row.revision,t('management.revoke'));await load()}catch{failed.value=true}finally{busy.value=false}}
onLoad(q=>{m.value=q?.m||''});onShow(()=>load());
</script>
<template><sh-scaffold title-key="management.grants"><view v-if="failed" class="sh-card" @tap="load()">{{t('management.retry')}}</view><view class="sh-card"><view class="sh-cell sh-row sh-row--between" @tap="chooseStaff"><text>{{t('management.staff')}}</text><text>{{actor?.displayName||t('management.choose')}}</text><sh-go/></view><view class="sh-cell sh-row sh-row--between" @tap="chooseResource"><text>{{t('management.resource')}}</text><text>{{resource?t('management.permission.'+resource.permissionCode.replaceAll('.','_')):t('management.choose')}}</text><sh-go/></view><view class="sh-btn" @tap="grant">{{t(busy?'management.loading':'management.grant')}}</view></view>
 <view v-for="row in rows" :key="row.grantNo" class="sh-card"><view class="sh-row sh-row--between"><text>{{t('management.permission.'+row.permissionCode.replaceAll('.','_'))}}</text><text class="sh-chip">{{t('management.state.'+row.status)}}</text></view><view class="sh-cell txt-sub sh-muted">{{row.actorLabel}} · {{row.resourceName}}</view><view v-if="row.status==='ACTIVE'" class="sh-btn sh-btn--danger" @tap="revoke(row)">{{t('management.revoke')}}</view></view><view v-if="next" class="sh-btn sh-btn--soft" @tap="load(true)">{{t('management.more')}}</view>
 <sh-sheet :visible="picking!==null" :title="t(picking==='staff'?'management.staff':'management.resource')" @close="picking=null"><template v-if="picking==='staff'"><view v-for="person in staff" :key="person.mchAccountNo" class="sh-cell" @tap="actor=person;picking=null">{{person.displayName||person.loginPhone}}</view></template><template v-else><view v-for="item in resources" :key="item.grantNo" class="sh-cell" @tap="resource=item;picking=null">{{item.resourceName}} · {{t('management.permission.'+item.permissionCode.replaceAll('.','_'))}}</view></template></sh-sheet>
 </sh-scaffold></template>
